def solve_mirror_pieces(text):
    tokens = text.split()
    q = int(tokens[0])
    out = []
    for tape in tokens[1:1 + q]:
        n = len(tape)
        best = [0] + [n] * n          # best[i]: fewest pieces for tape[:i]
        for centre in range(2 * n - 1):
            lo, hi = centre // 2, (centre + 1) // 2
            while lo >= 0 and hi < n and tape[lo] == tape[hi]:
                if best[lo] + 1 < best[hi + 1]:
                    best[hi + 1] = best[lo] + 1
                lo -= 1
                hi += 1
        out.append(str(best[n]))
    return '\n'.join(out)

