def solve_mirror_pieces(text):
    tokens = text.split()
    q = int(tokens[0])
    out = []
    for tape in tokens[1:1 + q]:
        n = len(tape)
        best = [n]

        def search(i, used):
            if i == n:
                best[0] = min(best[0], used)
                return
            if used + 1 >= best[0]:
                return
            for j in range(n, i, -1):
                if tape[i:j] == tape[i:j][::-1]:
                    search(j, used + 1)

        search(0, 0)
        out.append(str(best[0]))
    return '\n'.join(out)
